import hashlib
from Crypto.Hash import RIPEMD160
from pysmx.sm3 import sm3_hash

target_hash = "a60458d2180258d47d7f7bef5236b33e86711ac926518ca4545ebf24cdc0b76c"

# Common CTF inputs
test_inputs = [
    "a", "b", "c", "d", "e", "f", "g", "1", "2", "3",
    "flag", "ctf", "test", "hello", "world", "admin", "password",
    "secret", "key", "hash", "crypto"
]

# Supported algorithm names to use as salt
salt_names = [
    "sha256", "sha3256", "sha3_256", "sha3-256",
    "ripemd160", "ripemd-160", "ripemd256", "ripemd-256", 
    "sm3", "gost", "haval256", "haval-256",
    "snefru256", "snefru-256", "skein256", "skein-256"
]

def sm3_hex(data):
    return sm3_hash(data).hex()

def ripemd160_hex(data):
    ripe = RIPEMD160.new()
    ripe.update(data)
    return ripe.hexdigest()

def try_hash_with_salt(input_str, salt, hash_func, prepend=False):
    if prepend:
        data = (salt + input_str).encode()
    else:
        data = (input_str + salt).encode()
    return hash_func(data) == target_hash

print("Testing common inputs with different hash algorithms and salts...")
print("=" * 70)

# Test SHA-256
for input_str in test_inputs:
    for salt in salt_names:
        # Try with salt appended
        if try_hash_with_salt(input_str, salt, hashlib.sha256().hexdigest):
            print(f"Found match! SHA-256 of '{input_str}' + '{salt}' = {target_hash}")
            exit(0)

        # Try with salt prepended
        if try_hash_with_salt(input_str, salt, hashlib.sha256().hexdigest, True):
            print(f"Found match! SHA-256 of '{salt}' + '{input_str}' = {target_hash}")
            exit(0)

# Test SHA3-256
for input_str in test_inputs:
    for salt in salt_names:
        # Try with salt appended
        if try_hash_with_salt(input_str, salt, hashlib.sha3_256().hexdigest):
            print(f"Found match! SHA3-256 of '{input_str}' + '{salt}' = {target_hash}")
            exit(0)

        # Try with salt prepended
        if try_hash_with_salt(input_str, salt, hashlib.sha3_256().hexdigest, True):
            print(f"Found match! SHA3-256 of '{salt}' + '{input_str}' = {target_hash}")
            exit(0)

# Test SM3
for input_str in test_inputs:
    for salt in salt_names:
        data_appended = (input_str + salt).encode()
        if sm3_hex(data_appended) == target_hash:
            print(f"Found match! SM3 of '{input_str}' + '{salt}' = {target_hash}")
            exit(0)

        data_prepended = (salt + input_str).encode()
        if sm3_hex(data_prepended) == target_hash:
            print(f"Found match! SM3 of '{salt}' + '{input_str}' = {target_hash}")
            exit(0)

# Test RIPEMD-160
for input_str in test_inputs:
    for salt in salt_names:
        data_appended = (input_str + salt).encode()
        if ripemd160_hex(data_appended) == target_hash:
            print(f"Found match! RIPEMD-160 of '{input_str}' + '{salt}' = {target_hash}")
            exit(0)

        data_prepended = (salt + input_str).encode()
        if ripemd160_hex(data_prepended) == target_hash:
            print(f"Found match! RIPEMD-160 of '{salt}' + '{input_str}' = {target_hash}")
            exit(0)

print("No matches found in our comprehensive tests.")
